type Options = { remoteImages: boolean };
type Result = { css: string; blockedRemote: number };

// Split only at delimiters outside strings, parentheses and nested blocks. Invalid
// or incomplete input is discarded rather than repaired into a different rule.
function split(input: string, delimiter: string): string[] | null {
  const parts: string[] = [];
  let start = 0, quote = '', depth = 0;
  for (let i = 0; i < input.length; i++) {
    const c = input[i];
    if (quote) { if (c === quote) quote = ''; continue; }
    if (c === '"' || c === "'") { quote = c; continue; }
    if (c === '(' || c === '[' || c === '{') depth++;
    else if (c === ')' || c === ']' || c === '}') { if (--depth < 0) return null; }
    else if (c === delimiter && depth === 0) { parts.push(input.slice(start, i)); start = i + 1; }
  }
  if (quote || depth) return null;
  parts.push(input.slice(start));
  return parts;
}

function clean(input: string): string | null {
  let result = '', quote = '';
  for (let i = 0; i < input.length; i++) {
    const c = input[i];
    if (quote) { result += c; if (c === quote) quote = ''; continue; }
    if (c === '"' || c === "'") { quote = c; result += c; continue; }
    if (c === '/' && input[i + 1] === '*') {
      const end = input.indexOf('*/', i + 2);
      if (end < 0) return null;
      i = end + 1;
      continue;
    }
    result += c;
  }
  return quote ? null : result;
}

export function filterStyleAttribute(style: string, options: Options): Result {
  const input = clean(style);
  const declarations = input === null ? null : split(input, ';');
  let blockedRemote = 0;
  const kept: string[] = [];
  for (const declaration of declarations ?? []) {
    if (declaration.includes('\\')) continue;
    const colon = declaration.indexOf(':');
    if (colon < 1) continue;
    const property = declaration.slice(0, colon).trim().toLowerCase();
    const value = declaration.slice(colon + 1).trim();
    if (!/^-?[a-z][a-z0-9-]*$/.test(property) || !value || /expression\s*\(|javascript\s*:|vbscript\s*:|-moz-binding|behavior|image-set\s*\(|@import/i.test(value) || /^(behavior|-moz-binding)$/.test(property) || (property === 'position' && /\b(fixed|sticky)\b/i.test(value))) continue;
    let invalid = false, remote = 0, quote = '';
    for (let i = 0; i < value.length; i++) {
      const c = value[i];
      if (quote) { if (c === quote) quote = ''; continue; }
      if (c === '"' || c === "'") { quote = c; continue; }
      const match = /^url\s*\(/i.exec(value.slice(i));
      if (!match) continue;
      const start = i + match[0].length;
      let end = start, q = '';
      for (; end < value.length; end++) {
        const x = value[end];
        if (q) { if (x === q) q = ''; } else if (x === '"' || x === "'") q = x; else if (x === ')') break;
      }
      if (end === value.length) { invalid = true; break; }
      let url = value.slice(start, end).trim();
      if ((url.startsWith('"') && url.endsWith('"')) || (url.startsWith("'") && url.endsWith("'"))) url = url.slice(1, -1);
      if (/^https:\/\//i.test(url)) { if (!options.remoteImages) { invalid = true; remote++; } }
      else if (!/^cid:[^\s"'()]+$/i.test(url) && !/^data:image\/(png|jpeg|gif|webp);base64,[a-z0-9+/=]+$/i.test(url)) invalid = true;
      i = end;
    }
    blockedRemote += remote;
    if (!invalid) kept.push(`${property}: ${value}`);
  }
  return { css: kept.join('; '), blockedRemote };
}

export function filterCss(css: string, options: Options): Result {
  const input = clean(css);
  if (input === null || input.includes('\\')) return { css: '', blockedRemote: 0 };
  let position = 0, blockedRemote = 0;
  const kept: string[] = [];
  while (position < input.length) {
    let quote = '', parens = 0, open = -1;
    for (let i = position; i < input.length; i++) {
      const c = input[i];
      if (quote) { if (c === quote) quote = ''; continue; }
      if (c === '"' || c === "'") quote = c;
      else if (c === '(') parens++;
      else if (c === ')') parens--;
      else if (!parens && c === ';') { position = i + 1; }
      else if (!parens && c === '{') { open = i; break; }
      else if (!parens && c === '}') return { css: '', blockedRemote };
    }
    if (open < 0) break;
    const selector = input.slice(position, open).trim();
    let depth = 1, end = open + 1;
    quote = '';
    for (; end < input.length && depth; end++) {
      const c = input[end];
      if (quote) { if (c === quote) quote = ''; continue; }
      if (c === '"' || c === "'") quote = c;
      else if (c === '{') depth++;
      else if (c === '}') depth--;
    }
    if (depth || quote) return { css: '', blockedRemote };
    const body = input.slice(open + 1, end - 1);
    if (selector && !/[<>]/.test(selector)) {
      const at = selector.startsWith('@');
      if (!at || /^@(media|supports)\b/i.test(selector)) {
        const result = at ? filterCss(body, options) : filterStyleAttribute(body, options);
        blockedRemote += result.blockedRemote;
        if (result.css) kept.push(`${selector} { ${result.css} }`);
      }
    }
    position = end;
  }
  return { css: kept.join('\n'), blockedRemote };
}

