/**
 * HTML mail sanitiser (ADR 0006 decision 8).
 *
 * Mail HTML is parsed by DOMPurify into an inert document (DOMParser: no
 * browsing context, so nothing loads and no handler can run), cleaned there,
 * post-processed there, and serialised from there. The result is only ever
 * parsed again inside the sandboxed message frame. It is never parsed into the
 * app document (no innerHTML on app nodes), so a parser differential cannot
 * reach the app's realm or its IPC.
 *
 * After sanitising:
 * - no element has `href`; links keep their element and carry the target in
 *   `data-eos-href` (http, https and mailto only);
 * - `cid:` images carry `data-eos-cid`; remote https images carry
 *   `data-eos-src` / `data-eos-background` until the user loads images;
 * - style attributes and `<style>` text are filtered by `css-filter.ts`;
 * - a trailing quote is marked `data-eos-quote="trailing"`.
 */
import createDOMPurify from 'dompurify';
import { filterCss, filterStyleAttribute } from './css-filter';

export interface SanitizedMail {
  /** Filtered text of every `<style>` element, for the frame's head. */
  styles: string;
  /** `<div class="eos-mail-body" …>…</div>`: the cleaned body content. */
  body: string;
  /** Remote resources withheld because remote images are not loaded. */
  remoteBlocked: number;
  /** Content-IDs referenced by `cid:` images, unique, in document order. */
  cidReferences: string[];
  /** Whether the mail sets its own text or background colours (paper card). */
  hasOwnColours: boolean;
  /** Whether a trailing quote was found and marked. */
  hasTrailingQuote: boolean;
}

export interface SanitizeOptions {
  /** True once the user chose "Load images" for this message. */
  remoteImages: boolean;
}

/** Elements removed outright (ADR 0006 decision 8). */
const FORBIDDEN_TAGS = [
  'script', 'noscript', 'iframe', 'frame', 'frameset', 'object', 'embed', 'applet',
  'form', 'input', 'button', 'select', 'textarea', 'option', 'link', 'meta', 'base',
  'audio', 'video', 'source', 'track', 'portal', 'template', 'svg', 'math', 'title',
];

/** Of those, the ones whose content is dropped too (not just unwrapped). */
const FORBIDDEN_CONTENTS = [
  'script', 'noscript', 'iframe', 'frame', 'frameset', 'object', 'embed', 'applet',
  'form', 'select', 'textarea', 'option', 'audio', 'video', 'portal', 'template',
  'svg', 'math', 'title',
];

/** URL-bearing or behaviour attributes that never survive. */
const FORBIDDEN_ATTRIBUTES = new Set([
  'srcset', 'ping', 'formaction', 'xlink:href', 'action', 'target', 'poster', 'cite',
  'longdesc', 'lowsrc', 'dynsrc',
]);

/** Elements that may keep a (filtered) `background` image attribute. */
const BACKGROUND_TAGS = new Set(['TABLE', 'TD', 'TH', 'TR', 'BODY']);

/** Body attributes carried over to the wrapper so the mail keeps its canvas. */
const BODY_ATTRIBUTES = ['bgcolor', 'text', 'link', 'style', 'background', 'data-eos-background'];

/** Quote containers of common mail clients (ADR 0006 decision 17). */
const QUOTE_SELECTOR = [
  '.gmail_quote', 'blockquote[type="cite"]', '#divRplyFwdMsg', '#appendonsend',
  '.yahoo_quoted', '.protonmail_quote',
].join(', ');

const LINK_PROTOCOLS = new Set(['http:', 'https:', 'mailto:']);
const DATA_IMAGE = /^data:image\/(png|jpeg|gif|webp);base64,[a-z0-9+/=]+$/i;
const COLOUR_DECLARATION = /(?:^|[;{])\s*(?:color|background|background-color)\s*:/i;

export function sanitizeMailHtml(html: string, options: SanitizeOptions): SanitizedMail {
  const result: SanitizedMail = {
    styles: '',
    body: '',
    remoteBlocked: 0,
    cidReferences: [],
    hasOwnColours: false,
    hasTrailingQuote: false,
  };
  // A fresh instance per call: no hooks or configuration leak between calls.
  const purifier = createDOMPurify(window);
  const root = purifier.sanitize(html, {
    WHOLE_DOCUMENT: true,
    RETURN_DOM: true,
    USE_PROFILES: { html: true },
    ALLOW_DATA_ATTR: false,
    SANITIZE_DOM: true,
    FORBID_TAGS: FORBIDDEN_TAGS,
    FORBID_CONTENTS: FORBIDDEN_CONTENTS,
    ADD_TAGS: ['style'],
  }) as unknown as HTMLElement | null;
  const body = root?.querySelector('body');
  if (!root || !body) return result;

  collectStyles(root, options, result);
  markTrailingQuote(body, result);
  for (const element of [body, ...body.querySelectorAll('*')]) {
    cleanElement(element, options, result);
  }

  // Built in the inert document by moving nodes: never re-parsed here.
  const inert = body.ownerDocument;
  const wrapper = inert.createElement('div');
  wrapper.className = 'eos-mail-body';
  for (const name of BODY_ATTRIBUTES) {
    const value = body.getAttribute(name);
    if (value !== null) wrapper.setAttribute(name, value);
  }
  while (body.firstChild) wrapper.appendChild(body.firstChild);
  result.body = wrapper.outerHTML;
  return result;
}

/** Filters every `<style>` element into `styles` and removes it from the tree. */
function collectStyles(root: Element, options: SanitizeOptions, result: SanitizedMail): void {
  const styles: string[] = [];
  for (const style of root.querySelectorAll('style')) {
    const filtered = filterCss(style.textContent ?? '', options);
    result.remoteBlocked += filtered.blockedRemote;
    if (filtered.css) {
      styles.push(filtered.css);
      if (COLOUR_DECLARATION.test(filtered.css)) result.hasOwnColours = true;
    }
    style.remove();
  }
  result.styles = styles.join('\n');
}

/**
 * Marks the first quote container that ends the message: nothing with text or
 * an image follows it in document order outside it. For Outlook's separators
 * the quote is the separator and every sibling after it.
 */
function markTrailingQuote(body: HTMLElement, result: SanitizedMail): void {
  for (const candidate of body.querySelectorAll(QUOTE_SELECTOR)) {
    const separator = candidate.id === 'divRplyFwdMsg' || candidate.id === 'appendonsend';
    if (contentFollows(body, candidate, separator)) continue;
    candidate.setAttribute('data-eos-quote', 'trailing');
    if (separator) {
      for (let next = candidate.nextElementSibling; next; next = next.nextElementSibling) {
        next.setAttribute('data-eos-quote', 'trailing');
      }
    }
    result.hasTrailingQuote = true;
    return;
  }
}

/** Whether visible content follows `candidate` outside it, up to `body`. */
function contentFollows(body: HTMLElement, candidate: Element, separator: boolean): boolean {
  for (let node: Node | null = candidate; node && node !== body; node = node.parentNode) {
    // A separator's own following siblings are part of the quote.
    if (separator && node === candidate) continue;
    for (let next = node.nextSibling; next; next = next.nextSibling) {
      if ((next.textContent ?? '').trim()) return true;
      if (next instanceof Element && (next.matches('img') || next.querySelector('img'))) return true;
    }
  }
  return false;
}

/** Applies the attribute, link, image and style rules to one element. */
function cleanElement(element: Element, options: SanitizeOptions, result: SanitizedMail): void {
  for (const attribute of [...element.attributes]) {
    const name = attribute.name.toLowerCase();
    if (name.startsWith('on') || FORBIDDEN_ATTRIBUTES.has(name)) {
      element.removeAttribute(attribute.name);
    }
  }
  cleanLink(element);

  if (element.tagName === 'IMG') {
    cleanImageAttribute(element, 'src', options, result);
  } else {
    element.removeAttribute('src');
  }
  if (BACKGROUND_TAGS.has(element.tagName)) {
    cleanImageAttribute(element, 'background', options, result);
  } else {
    element.removeAttribute('background');
  }

  const style = element.getAttribute('style');
  if (style !== null) {
    const filtered = filterStyleAttribute(style, options);
    result.remoteBlocked += filtered.blockedRemote;
    if (filtered.css) {
      element.setAttribute('style', filtered.css);
      if (COLOUR_DECLARATION.test(filtered.css)) result.hasOwnColours = true;
    } else {
      element.removeAttribute('style');
    }
  }

  if (declaresColours(element)) result.hasOwnColours = true;
}

/** Moves an `<a href>` target to `data-eos-href`; no `href` survives anywhere. */
function cleanLink(element: Element): void {
  const href = element.getAttribute('href');
  if (href === null) return;
  element.removeAttribute('href');
  if (element.tagName !== 'A') return;
  let url: URL;
  try {
    url = new URL(href.trim());
  } catch {
    return; // Relative and malformed links are dropped.
  }
  if (!LINK_PROTOCOLS.has(url.protocol)) return;
  element.setAttribute('data-eos-href', url.href);
  element.setAttribute('role', 'link');
  element.setAttribute('tabindex', '0');
}

/** `cid:` → data-eos-cid; data images stay; https → src or withheld; else dropped. */
function cleanImageAttribute(
  element: Element,
  attribute: 'src' | 'background',
  options: SanitizeOptions,
  result: SanitizedMail,
): void {
  const value = element.getAttribute(attribute)?.trim();
  element.removeAttribute(attribute);
  if (!value) return;

  if (/^cid:/i.test(value)) {
    let cid: string;
    try {
      cid = decodeURIComponent(value.slice(4));
    } catch {
      return; // Invalid percent-encoding is dropped.
    }
    if (!cid) return;
    element.setAttribute('data-eos-cid', cid);
    if (!result.cidReferences.includes(cid)) result.cidReferences.push(cid);
    return;
  }
  if (DATA_IMAGE.test(value)) {
    element.setAttribute(attribute, value);
    return;
  }
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return; // Relative and malformed URLs are dropped.
  }
  if (url.protocol !== 'https:') return;
  if (options.remoteImages) {
    element.setAttribute(attribute, url.href);
  } else {
    element.setAttribute(attribute === 'background' ? 'data-eos-background' : 'data-eos-src', url.href);
    result.remoteBlocked += 1;
  }
}

/** Presentational colour attributes (ADR 0006 decision 15). */
function declaresColours(element: Element): boolean {
  if (element.hasAttribute('bgcolor') || element.hasAttribute('background')) return true;
  if (element.hasAttribute('data-eos-background')) return true;
  if (element.tagName === 'FONT' && element.hasAttribute('color')) return true;
  if (element.tagName === 'BODY' && (element.hasAttribute('text') || element.hasAttribute('link'))) {
    return true;
  }
  return false;
}

/**
 * CSS filter for HTML mail (ADR 0006 decision 8).
 *
 * A small string-aware tokenizer, not regexes over the whole text: it respects
 * quoted strings, parentheses and nested blocks, removes comments first, and
 * re-serialises only the selectors and declarations it kept, so malformed input
 * cannot leak through. Anything it cannot parse is dropped, never repaired.
 *
 * Rules:
 * - a backslash anywhere drops the declaration (or the whole stylesheet):
 *   CSS escapes are how filters get bypassed and mail rarely needs them;
 * - `<` anywhere drops the declaration or rule, so filtered text placed in a
 *   `<style>` element can never close it;
 * - only `@media` and `@supports` at-rules are kept (filtered recursively);
 * - declarations with `expression(`, `javascript:`, `vbscript:`, `-moz-binding`,
 *   `behavior`, `image-set(` or `@import`, and `position: fixed|sticky`, are
 *   dropped;
 * - `url()` is allowed for `data:image/(png|jpeg|gif|webp);base64` and `cid:`;
 *   `https:` only when remote images are loaded (otherwise the declaration is
 *   dropped and counted); every other URL drops the declaration.
 */

export interface CssFilterOptions {
  remoteImages: boolean;
}

export interface CssFilterResult {
  css: string;
  /** Declarations dropped only because they would load a remote resource. */
  blockedRemote: number;
}

const FORBIDDEN_VALUE = /expression\s*\(|javascript\s*:|vbscript\s*:|-moz-binding|behavior|image-set\s*\(|@import/i;
const PROPERTY_NAME = /^-?[a-z][a-z0-9-]*$/;
const DATA_IMAGE_URL = /^data:image\/(png|jpeg|gif|webp);base64,[a-z0-9+/=]+$/i;
const CID_URL = /^cid:[^\s"'()]+$/i;
const KEPT_AT_RULE = /^@(media|supports)\b/i;

/** Filters the text of one `<style>` element. */
export function filterCss(css: string, options: CssFilterOptions): CssFilterResult {
  const input = stripComments(css);
  if (input === null || input.includes('\\')) return { css: '', blockedRemote: 0 };
  return filterRules(input, options);
}

/** Filters one `style="…"` attribute value. */
export function filterStyleAttribute(style: string, options: CssFilterOptions): CssFilterResult {
  const input = stripComments(style);
  if (input === null) return { css: '', blockedRemote: 0 };
  return filterDeclarations(input, options);
}

/** Top-level rules: `selector { … }` and at-rules; anything malformed ends the sheet. */
function filterRules(input: string, options: CssFilterOptions): CssFilterResult {
  const kept: string[] = [];
  let blockedRemote = 0;
  let position = 0;
  while (position < input.length) {
    const open = findBlockStart(input, position);
    if (open === 'malformed') return { css: kept.join('\n'), blockedRemote };
    if (open.index < 0) break;
    const close = findBlockEnd(input, open.index);
    if (close < 0) return { css: kept.join('\n'), blockedRemote };

    const selector = input.slice(open.start, open.index).trim();
    const block = input.slice(open.index + 1, close);
    position = close + 1;
    if (!selector || selector.includes('<')) continue;

    if (selector.startsWith('@')) {
      if (!KEPT_AT_RULE.test(selector)) continue;
      const inner = filterRules(block, options);
      blockedRemote += inner.blockedRemote;
      if (inner.css) kept.push(`${selector} {\n${inner.css}\n}`);
    } else {
      const declarations = filterDeclarations(block, options);
      blockedRemote += declarations.blockedRemote;
      if (declarations.css) kept.push(`${selector} { ${declarations.css} }`);
    }
  }
  return { css: kept.join('\n'), blockedRemote };
}

/**
 * Finds the `{` that opens the next block after `from`, skipping strings,
 * parenthesised text and statement at-rules ending in `;` (such as
 * `@import …;`, which are thereby dropped). `start` is where its prelude begins.
 */
function findBlockStart(
  input: string,
  from: number,
): { start: number; index: number } | 'malformed' {
  let start = from;
  let quote = '';
  let parens = 0;
  for (let i = from; i < input.length; i += 1) {
    const c = input[i];
    if (quote) {
      if (c === quote) quote = '';
      continue;
    }
    if (c === '"' || c === "'") quote = c;
    else if (c === '(') parens += 1;
    else if (c === ')') parens -= 1;
    else if (parens === 0 && c === ';') start = i + 1;
    else if (parens === 0 && c === '{') return { start, index: i };
    else if (parens === 0 && c === '}') return 'malformed';
  }
  return { start, index: -1 };
}

/** Index of the `}` matching the `{` at `open`, or -1 when unbalanced. */
function findBlockEnd(input: string, open: number): number {
  let depth = 0;
  let quote = '';
  for (let i = open; i < input.length; i += 1) {
    const c = input[i];
    if (quote) {
      if (c === quote) quote = '';
      continue;
    }
    if (c === '"' || c === "'") quote = c;
    else if (c === '{') depth += 1;
    else if (c === '}') {
      depth -= 1;
      if (depth === 0) return i;
    }
  }
  return -1;
}

/** `prop: value; …` → the kept declarations, re-serialised. */
function filterDeclarations(input: string, options: CssFilterOptions): CssFilterResult {
  const declarations = splitTopLevel(input, ';');
  if (declarations === null) return { css: '', blockedRemote: 0 };
  const kept: string[] = [];
  let blockedRemote = 0;
  for (const declaration of declarations) {
    if (declaration.includes('\\') || declaration.includes('<')) continue;
    const colon = declaration.indexOf(':');
    if (colon < 1) continue;
    const property = declaration.slice(0, colon).trim().toLowerCase();
    const value = declaration.slice(colon + 1).trim();
    if (!PROPERTY_NAME.test(property) || !value) continue;
    if (property === 'behavior' || property === '-moz-binding') continue;
    if (FORBIDDEN_VALUE.test(value)) continue;
    if (property === 'position' && /\b(fixed|sticky)\b/i.test(value)) continue;

    const urls = checkUrls(value, options);
    if (urls === 'remote') {
      blockedRemote += 1;
      continue;
    }
    if (urls === 'forbidden') continue;
    kept.push(`${property}: ${value}`);
  }
  return { css: kept.join('; '), blockedRemote };
}

/** Classifies every `url(…)` in a declaration value. */
function checkUrls(value: string, options: CssFilterOptions): 'ok' | 'remote' | 'forbidden' {
  let quote = '';
  let verdict: 'ok' | 'remote' = 'ok';
  for (let i = 0; i < value.length; i += 1) {
    const c = value[i];
    if (quote) {
      if (c === quote) quote = '';
      continue;
    }
    if (c === '"' || c === "'") {
      quote = c;
      continue;
    }
    const match = /^url\s*\(/i.exec(value.slice(i));
    if (!match) continue;
    const start = i + match[0].length;
    const end = findUrlEnd(value, start);
    if (end < 0) return 'forbidden';
    let url = value.slice(start, end).trim();
    const quoted = (url.startsWith('"') && url.endsWith('"')) || (url.startsWith("'") && url.endsWith("'"));
    if (quoted) url = url.slice(1, -1);
    if (/^https:\/\//i.test(url)) {
      if (!options.remoteImages) verdict = 'remote';
    } else if (!CID_URL.test(url) && !DATA_IMAGE_URL.test(url)) {
      return 'forbidden';
    }
    i = end;
  }
  return verdict;
}

/** Index of the `)` closing a `url(` whose argument starts at `start`. */
function findUrlEnd(value: string, start: number): number {
  let quote = '';
  for (let i = start; i < value.length; i += 1) {
    const c = value[i];
    if (quote) {
      if (c === quote) quote = '';
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === ')') {
      return i;
    }
  }
  return -1;
}

/** Splits at `delimiter` outside strings, parentheses and blocks; null when unbalanced. */
function splitTopLevel(input: string, delimiter: string): string[] | null {
  const parts: string[] = [];
  let start = 0;
  let quote = '';
  let depth = 0;
  for (let i = 0; i < input.length; i += 1) {
    const c = input[i];
    if (quote) {
      if (c === quote) quote = '';
      continue;
    }
    if (c === '"' || c === "'") {
      quote = c;
      continue;
    }
    if (c === '(' || c === '[' || c === '{') {
      depth += 1;
    } else if (c === ')' || c === ']' || c === '}') {
      depth -= 1;
      if (depth < 0) return null;
    } else if (c === delimiter && depth === 0) {
      parts.push(input.slice(start, i));
      start = i + 1;
    }
  }
  if (quote || depth) return null;
  parts.push(input.slice(start));
  return parts;
}

/** Removes `/* … *\/` comments outside strings; null when one is unterminated. */
function stripComments(input: string): string | null {
  let output = '';
  let quote = '';
  for (let i = 0; i < input.length; i += 1) {
    const c = input[i];
    if (quote) {
      output += c;
      if (c === quote) quote = '';
      continue;
    }
    if (c === '"' || c === "'") {
      quote = c;
      output += c;
      continue;
    }
    if (c === '/' && input[i + 1] === '*') {
      const end = input.indexOf('*/', i + 2);
      if (end < 0) return null;
      i = end + 1;
      continue;
    }
    output += c;
  }
  return quote ? null : output;
}

