21	impl<'a> Extractor<'a> {
22	    fn new(html: &'a str, limit: usize) -> Self {
23	        Self { html, pos: 0, output: String::new(), count: 0, limit, pending: 0, pre: 0, links: Vec::new(), link: None }
24	    }
25	
26	    fn run(mut self) -> String {
27	        while self.pos < self.html.len() && self.count < self.limit {
28	            let b = self.html.as_bytes()[self.pos];
29	            if b == b'<' && self.html.as_bytes().get(self.pos + 1).is_some_and(|c| c.is_ascii_alphabetic() || matches!(c, b'/' | b'!' | b'?')) {
30	                self.tag();
31	            } else if b == b'&' {
32	                let (chars, consumed) = Self::reference(&self.html[self.pos..]);
33	                self.pos += consumed;
34	                for c in chars.into_iter().flatten() { self.text(c); }
35	            } else if let Some(c) = self.html[self.pos..].chars().next() {
36	                self.pos += c.len_utf8();
37	                self.text(c);
38	            }
39	        }
40	        while self.output.ends_with(' ') || self.output.ends_with('\n') || self.output.ends_with('\t') {
41	            self.output.pop();
42	            self.count -= 1;
43	        }
44	        if self.count < self.limit {
45	            for (i, url) in self.links.iter().enumerate() {
46	                let line = format!("{}[{}]: {}", if i == 0 { "\n\n" } else { "\n" }, i + 1, url);
47	                let n = line.chars().count();
48	                if self.count + n > self.limit { break; }
49	                self.output.push_str(&line);
50	                self.count += n;
51	            }
52	        }
53	        self.output
54	    }
