56	    fn emit(&mut self, c: char) {
57	        if self.count < self.limit { self.output.push(c); self.count += 1; }
58	    }
59	
60	    fn flush(&mut self) {
61	        if !self.output.is_empty() {
62	            let pending = self.pending;
63	            self.pending = 0;
64	            for _ in 0..pending { self.emit('\n'); }
65	        } else { self.pending = 0; }
66	    }
67	
68	    fn newline(&mut self, blank: bool) {
69	        while self.output.ends_with(' ') || self.output.ends_with('\t') { self.output.pop(); self.count -= 1; }
70	        if !self.output.is_empty() { self.pending = self.pending.max(if blank { 2 } else { 1 }); }
71	    }
