73	    fn text(&mut self, c: char) {
74	        if (c as u32 <= 0x1f || (0x7f..=0x9f).contains(&(c as u32))) && c != '\n' && c != '\t' { return; }
75	        if self.pre == 0 && c.is_whitespace() {
76	            if self.pending == 0 && !self.output.is_empty() && !self.output.ends_with(' ') && !self.output.ends_with('\n') { self.emit(' '); }
77	        } else {
78	            self.flush();
79	            self.emit(c);
80	        }
81	    }
