83	    /// The numeric scan consumes its entire candidate once; named lookups inspect at most 33 bytes.
84	    fn reference(s: &str) -> ([Option<char>; 2], usize) {
85	        let bytes = s.as_bytes();
86	        if bytes.get(1) == Some(&b'#') {
87	            let mut i = 2;
88	            let radix = if matches!(bytes.get(i), Some(b'x' | b'X')) { i += 1; 16 } else { 10 };
89	            let start = i;
90	            let mut value = 0u32;
91	            while let Some(&b) = bytes.get(i) {
92	                let digit = (b as char).to_digit(radix);
93	                let Some(digit) = digit else { break };
94	                value = value.saturating_mul(radix).saturating_add(digit);
95	                i += 1;
96	            }
97	            if i == start { return ([Some('&'), None], 1); }
98	            if bytes.get(i) == Some(&b';') { i += 1; }
99	            let c = if value == 0 { '\u{fffd}' } else { char::from_u32(value).unwrap_or('\u{fffd}') };
100	            return ([Some(c), None], i);
101	        }
102	        let mut best = None;
103	        for end in 1..=bytes.len().saturating_sub(1).min(33) {
104	            let b = bytes[end];
105	            if !b.is_ascii_alphanumeric() && b != b';' { break; }
106	            if let Some(&(a, b)) = NAMED_ENTITIES.get(&s[1..=end]) {
107	                if a != 0 { best = Some((a, b, end + 1)); }
108	            }
109	            if b == b';' { break; }
110	        }
111	        if let Some((a, b, n)) = best {
112	            ([char::from_u32(a), if b == 0 { None } else { char::from_u32(b) }], n)
113	        } else { ([Some('&'), None], 1) }
114	    }
