116	    /// Each tag scan advances the cursor to its end, or consumes the remaining input.
117	    fn tag(&mut self) {
118	        let start = self.pos;
119	        let bytes = self.html.as_bytes();
120	        if self.html[start..].starts_with("<!--") {
121	            self.pos = self.html[start + 4..].find("-->").map_or(bytes.len(), |n| start + 4 + n + 3);
122	            return;
123	        }
124	        if self.html[start..].starts_with("<![CDATA[") {
