204	    /// Each byte in the skipped region is inspected a constant number of times, including malformed tags.
205	    fn skip_raw(&mut self, name: &str, nested: bool) {
206	        let bytes = self.html.as_bytes();
207	        let mut depth = 1usize;
208	        while self.pos < bytes.len() {
209	            if bytes[self.pos] != b'<' { self.pos += 1; continue; }
210	            self.pos += 1;
211	            let closing = bytes.get(self.pos) == Some(&b'/');
212	            if closing { self.pos += 1; }
213	            let start = self.pos;
214	            while bytes.get(self.pos).is_some_and(|b| b.is_ascii_alphanumeric() || *b == b'-') { self.pos += 1; }
215	            let matches = self.html.get(start..self.pos).is_some_and(|s| s.eq_ignore_ascii_case(name));
216	            let boundary = bytes.get(self.pos).is_some_and(|b| b.is_ascii_whitespace() || *b == b'>' || *b == b'/');
