218	                let mut quote = 0;
219	                while self.pos < bytes.len() {
220	                    let b = bytes[self.pos]; self.pos += 1;
221	                    if quote != 0 { if b == quote { quote = 0; } }
222	                    else if b == b'\'' || b == b'"' { quote = b; }
223	                    else if b == b'>' { break; }
224	                }
225	                if closing { depth = depth.saturating_sub(1); if depth == 0 { return; } }
226	                else { depth = depth.saturating_add(1); }
227	            }
228	        }
229	    }
