fn hostile_inputs_are_bounded_and_fast() {
        let mut cases = vec![format!("<tr>{}</tr>", "<td>a</td>".repeat(50_000)), "<td colspan=1000000>x</td>".into(), format!("{}visible", "<div>".repeat(90_000))];
